package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LendingIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loaning_a_book_already_on_loan_returns_409() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.status").value("AVAILABLE"))
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        String loanRequest = objectMapper.writeValueAsString(new LoanBody(book.get("id").asText(), registerMember("이서준")));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.bookId").value(book.get("id").asText()));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_ALREADY_ON_LOAN"));
    }

    @Test
    void registered_member_can_be_fetched_by_id() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.memberId").isNotEmpty())
                .andExpect(jsonPath("$.name").value("김민지"))
                .andReturn().getResponse().getContentAsString();
        String memberId = objectMapper.readTree(registered).get("memberId").asText();

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.memberId").value(memberId))
                .andExpect(jsonPath("$.name").value("김민지"));
    }

    @Test
    void registering_member_with_blank_name_returns_400() throws Exception {
        for (String body : new String[]{"{\"name\":\"\"}", "{\"name\":\"   \"}", "{}"}) {
            mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON).content(body))
                    .andExpect(status().isBadRequest());
        }
    }

    @Test
    void fetching_unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void registered_book_can_be_fetched_by_id() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Domain-Driven Design\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        String bookId = objectMapper.readTree(registered).get("id").asText();

        mockMvc.perform(get("/books/{id}", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(bookId))
                .andExpect(jsonPath("$.title").value("Domain-Driven Design"))
                .andExpect(jsonPath("$.status").value("AVAILABLE"));
    }

    @Test
    void loaning_a_sixth_book_while_holding_five_returns_409() throws Exception {
        String memberId = registerMember("박지훈");
        for (int i = 1; i <= 5; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                            .content(objectMapper.writeValueAsString(new LoanBody(registerBook("책 " + i), memberId))))
                    .andExpect(status().isCreated());
        }

        String sixthBookId = registerBook("책 6");
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(sixthBookId, memberId))))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));

        mockMvc.perform(get("/books/{id}", sixthBookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("AVAILABLE"));
    }

    @Test
    void loaning_with_unknown_member_returns_404() throws Exception {
        String bookId = registerBook("Refactoring");

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(bookId, UUID.randomUUID().toString()))))
                .andExpect(status().isNotFound());

        mockMvc.perform(get("/books/{id}", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("AVAILABLE"));
    }

    private String registerBook(String title) throws Exception {
        String response = mockMvc.perform(post("/books").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new TitleBody(title))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("id").asText();
    }

    private String registerMember(String name) throws Exception {
        String response = mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new NameBody(name))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("memberId").asText();
    }

    record TitleBody(String title) {
    }

    record NameBody(String name) {
    }

    record LoanBody(String bookId, String memberId) {
    }
}
